SELECT 'paper_position' AS src, p.id, p.symbol, p.status, p.realized_pnl, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(p.opened_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS opened_utc, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(p.closed_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS closed_utc FROM paper_position p ORDER BY p.id DESC LIMIT 10;
SELECT 'trade_signal' AS src, s.id, s.symbol, s.interval_code, s.decision, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(s.generated_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS generated_utc FROM trade_signal s ORDER BY s.id DESC LIMIT 5;